-- 0128: the 12 lemma arcs of Ghāfir 40:2–3, rebuilt from the COMBINED all-lexicon arc
-- (ar_ling_arc_rung source_slug='combined': every book read by its own markers, Lane in English).
-- Each step is a root-scope sense tied to its combined rung(s); each step's attestations are copied
-- from the per-book rungs that make up that combined rung — so every step carries every book that
-- gives it, in that book's own words. The last step is the lemma's Qurʾānic sense (0125).
-- Every attestation keeps the lexicon block it came from (block_id), so each step backlinks to
-- the exact passage in each book. The step itself is plain English; the books' words sit behind it.
-- Replaces the Ibn Fāris-only arc_en of 0125 (AGR:VOC:002). إِلَٰه keeps its live AL arc.

-- نزل: coming down → sending down → set in its place, part by part → the Revelation
UPDATE ar_ling_sense_arc SET arc_en = 'coming down → sending down → set in its place, part by part → the Revelation', updated_at = datetime('now') WHERE id = 'ARC:نزل:tanzil';
DELETE FROM ar_ling_sense_attestation WHERE target_type = 'arc_step' AND target_id IN (SELECT id FROM ar_ling_sense_arc_step WHERE arc_id = 'ARC:نزل:tanzil');
DELETE FROM ar_ling_sense_arc_step WHERE arc_id = 'ARC:نزل:tanzil';
