INSERT OR IGNORE INTO ar_ling_sense_arc_step (id, arc_id, step_no, sense_id, note_md) VALUES ('ARCS:نزل:tanzil:1', 'ARC:نزل:tanzil', 1, 'SNS:نزل:cmb1', 'combined rung(s) 1, 2');
